message.content:
{
 "action": "film_Alma",
 "words": "I need to go. The Rialto is closing, and I have to get this down before the light goes out.",
 "intention": "To capture the final moment of the projectionist's life before the theater closes and the regional line takes the reel away.",
 "detail": "Shoulders tense, I tighten the strap of the camera bag and walk away from the coffee table without waiting for a reply. The battery is fully charged; I have one take. I head straight for the Rialto."
}
